import 'package:flutter/material.dart';
import '../../core/api_client.dart';
import '../../core/format.dart';
class TransactionsScreen extends StatefulWidget{const TransactionsScreen({super.key});@override State<TransactionsScreen> createState()=>_TransactionsScreenState();}
class _TransactionsScreenState extends State<TransactionsScreen>{List rows=[];bool loading=true;String filter='all';Future<void> load()async{setState(()=>loading=true);try{final v=await ApiClient.instance.get('/transactions',filter=='all'?null:{'type':filter});if(mounted)setState(()=>rows=v as List);}catch(e){if(mounted)ScaffoldMessenger.of(context).showSnackBar(SnackBar(content:Text(ApiClient.instance.message(e))));}finally{if(mounted)setState(()=>loading=false);}}@override void initState(){super.initState();load();}@override Widget build(BuildContext context)=>Column(children:[Padding(padding:const EdgeInsets.all(20),child:Row(children:[const Expanded(child:Text('Transactions',style:TextStyle(fontSize:26,fontWeight:FontWeight.w800))),IconButton(onPressed:load,icon:const Icon(Icons.refresh))])),Padding(padding:const EdgeInsets.symmetric(horizontal:16),child:SegmentedButton<String>(segments:const[ButtonSegment(value:'all',label:Text('All')),ButtonSegment(value:'expense',label:Text('Expenses')),ButtonSegment(value:'income',label:Text('Income'))],selected:{filter},onSelectionChanged:(v){setState(()=>filter=v.first);load();})),Expanded(child:loading?const Center(child:CircularProgressIndicator()):RefreshIndicator(onRefresh:load,child:ListView.builder(itemCount:rows.length,itemBuilder:(c,i){final t=rows[i];return Card(child:ListTile(title:Text(t['category_name']?.toString()??t['note']?.toString()??'Transaction'),subtitle:Text(t['txn_date'].toString()+' · '+t['type'].toString()),trailing:Text(formatMoney(t['amount'] as num?))));}))) ]);}
